import { z } from "zod";
import { isAiConfigured } from "@/lib/ai/client";
import { callScenarioSchema } from "@/lib/ai/conversation";
import { assertQuota, QuotaExceededError } from "@/lib/ai/quota";
import { createClient } from "@/lib/supabase/server";

const createSchema = z.object({
  setId: z.uuid(),
  scenario: callScenarioSchema,
});

/**
 * Creates an empty AI call thread for a vocabulary set. The opening greeting is
 * generated by the first turn request (start flag) so quota and usage stay in
 * one place.
 */
export async function POST(request: Request) {
  const signal = AbortSignal.any([request.signal, AbortSignal.timeout(15_000)]);
  if (signal.aborted) return new Response(null, { status: 408 });
  try {
    const supabase = await createClient();
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) return Response.json({ error: "Bạn cần đăng nhập để luyện hội thoại." }, { status: 401 });
    if (!isAiConfigured()) {
      return Response.json({ error: "AI chưa được bật. Hãy thử lại sau." }, { status: 503 });
    }

    const body = createSchema.safeParse(await request.json().catch(() => null));
    if (!body.success) return Response.json({ error: "Kịch bản không hợp lệ." }, { status: 400 });
    const { setId, scenario } = body.data;

    const [set, cards] = await Promise.all([
      supabase.from("study_sets").select("id").eq("id", setId).abortSignal(signal).maybeSingle(),
      supabase.from("cards").select("id", { count: "exact", head: true }).eq("set_id", setId).abortSignal(signal),
    ]);
    signal.throwIfAborted();
    if (set.error || cards.error) throw new Error("Could not load call inputs");
    if (!set.data) return Response.json({ error: "Không tìm thấy bộ từ." }, { status: 404 });
    if (!cards.count) {
      return Response.json({ error: "Bộ từ chưa có thẻ để luyện hội thoại." }, { status: 422 });
    }

    await assertQuota(supabase, user.id, "conversation");
    const { data: thread, error } = await supabase
      .from("chat_threads")
      .insert({ user_id: user.id, set_id: setId, scenario })
      .select("id")
      .abortSignal(signal)
      .single();
    if (error || !thread) throw error ?? new Error("Could not create thread");
    return Response.json({ threadId: thread.id });
  } catch (error) {
    if (signal.aborted) return Response.json({ error: "Tạo cuộc gọi quá lâu. Hãy thử lại." }, { status: 504 });
    if (error instanceof QuotaExceededError) return Response.json({ error: error.message }, { status: 429 });
    console.error("AI call create failed", error instanceof Error ? error.message : error);
    return Response.json({ error: "Chưa tạo được cuộc gọi. Hãy thử lại." }, { status: 502 });
  }
}
